## Deployment Strategies

### 1. Docker Deployment

```dockerfile
# Dockerfile
FROM node:18-alpine

# Set environment
ENV NODE_ENV=production

# Install dependencies
WORKDIR /app
COPY package*.json ./
RUN npm ci --only=production

# Copy application
COPY . .

# Build application
RUN npm run build

# Start application
CMD ["npm", "start"]
```

```yaml
# docker-compose.yml
version: '3.8'
services:
  app:
    build: .
    environment:
      - NODE_ENV=production
      - OPENROUTER_API_KEY=${OPENROUTER_API_KEY}
    ports:
      - "3000:3000"
    depends_on:
      - redis

  redis:
    image: redis:alpine
    ports:
      - "6379:6379"
```

### 2. Kubernetes Deployment

```yaml
# kubernetes/deployment.yaml
apiVersion: apps/v1
kind: Deployment
metadata:
  name: openrouter-deployment
spec:
  replicas: 3
  selector:
    matchLabels:
      app: openrouter
  template:
    metadata:
      labels:
        app: openrouter
    spec:
      containers:
      - name: openrouter
        image: openrouter:latest
        env:
        - name: NODE_ENV
          value: "production"
        - name: OPENROUTER_API_KEY
          valueFrom:
            secretKeyRef:
              name: openrouter-secrets
              key: api-key
        resources:
          requests:
            memory: "1Gi"
            cpu: "500m"
          limits:
            memory: "2Gi"
            cpu: "1000m"
```

### 3. Serverless Deployment

```typescript
// serverless.ts
import { OpenRouterModel } from 'dspy.ts';

export const handler = async (event: any) => {
  const model = new OpenRouterModel({
    // Production configuration
    environment: 'production',
    timeout: 30000,
    memory: '2GB'
  });

  try {
    const result = await model.generate(event.prompt);
    return {
      statusCode: 200,
      body: JSON.stringify(result)
    };
  } catch (error) {
    return {
      statusCode: 500,
      body: JSON.stringify({ error: error.message })
    };
  }
};
```

